"""Balanced bracket checker that ignores text inside double-quoted strings."""

PAIRS = {")": "(", "]": "[", "}": "{"}


def balanced(s):
    """Return True when every (), [], {} in *s* is properly matched.

    Text inside a double-quoted string is ignored.  Within such a string a
    backslash escapes the next character, so \" does not end the string.  An
    unterminated string makes the whole input unbalanced.
    """
    stack = []
    in_string = False
    escaped = False

    for ch in s:
        if in_string:
            if escaped:
                escaped = False
            elif ch == "\\":
                escaped = True
            elif ch == '"':
                in_string = False
            continue

        if ch == '"':
            in_string = True
        elif ch in "([{":
            stack.append(ch)
        elif ch in ")]}":
            if not stack or stack[-1] != PAIRS[ch]:
                return False
            stack.pop()

    return not in_string and not stack
